package contracts.governance

import scala.collection.mutable
import scala.util.{Try, Success, Failure}
import java.time.Instant
import java.security.MessageDigest

// Smart contract expression evaluator for governance proposals
object ExpressionEngine {
  sealed trait Expr
  case class Literal(value: Long) extends Expr
  case class VarRef(name: String) extends Expr
  case class BinOp(op: String, left: Expr, right: Expr) extends Expr
  case class FuncCall(name: String, args: List[Expr]) extends Expr

  private val allowedFunctions = Set("min", "max", "abs", "sqrt")
  private val allowedOps = Set("+", "-", "*", "/", "%", "==", "!=", "<", ">")

  def validateExpr(expr: Expr, boundVars: Set[String]): Boolean = expr match {
    case Literal(_) => true
    case VarRef(n) => boundVars.contains(n)
    case BinOp(op, l, r) => allowedOps.contains(op) && validateExpr(l, boundVars) && validateExpr(r, boundVars)
    case FuncCall(name, args) => allowedFunctions.contains(name) && args.forall(validateExpr(_, boundVars))
  }
}

// Audit log with expression-based filtering
class AuditLog {
  case class LogEntry(timestamp: Long, actor: String, action: String, details: String, blockHeight: Long)

  private val entries = mutable.ArrayBuffer[LogEntry]()

  def append(actor: String, action: String, details: String, blockHeight: Long): Unit = {
    entries += LogEntry(Instant.now.toEpochMilli, actor, action, details, blockHeight)
  }

  // Safe filter: only supports exact field matching with whitelisted fields
  def compileFilter(field: String, value: String): LogEntry => Boolean = {
    val sanitizedValue = value.replaceAll("[^a-zA-Z0-9_=\\-@.]", "")
    field match {
      case "actor" => (entry: LogEntry) => entry.actor == sanitizedValue
      case "action" => (entry: LogEntry) => entry.action == sanitizedValue
      case _ => (_: LogEntry) => true
    }
  }

  def query(filter: LogEntry => Boolean): Seq[LogEntry] = {
    entries.filter(filter).toSeq
  }
}

// Governance contract with proposal execution
class GovernanceContract(val contractAddress: String) {
  import ExpressionEngine._

  private val auditLog = new AuditLog()
  private val stateVars = mutable.HashMap[String, Long]("treasury" -> 1000000L, "quorum" -> 51L)
  private val proposals = mutable.HashMap[String, Proposal]()

  case class Proposal(id: String, title: String, expression: String, proposer: String, votes: mutable.HashMap[String, Boolean] = mutable.HashMap())

  def propose(id: String, title: String, expression: String, proposer: String): Either[String, String] = {
    // Validate the expression AST before accepting
    parseExpression(expression) match {
      case Some(ast) =>
        if (ExpressionEngine.validateExpr(ast, stateVars.keySet.toSet ++ Set("amount", "target"))) {
          proposals(id) = Proposal(id, title, expression, proposer)
          auditLog.append(proposer, "PROPOSE", s"id=$id", currentBlock())
          Right(id)
        } else {
          Left("Expression validation failed")
        }
      case None => Left("Parse error")
    }
  }

  def vote(proposalId: String, voter: String, approve: Boolean): Either[String, Unit] = {
    proposals.get(proposalId) match {
      case Some(p) =>
        p.votes(voter) = approve
        auditLog.append(voter, "VOTE", s"proposal=$proposalId approve=$approve", currentBlock())
        Right(())
      case None => Left("Proposal not found")
    }
  }

  def execute(proposalId: String, executor: String): Either[String, Long] = {
    proposals.get(proposalId) match {
      case Some(p) if hasQuorum(p) =>
        val result = evaluateExpression(p.expression, buildContext(p))
        auditLog.append(executor, "EXECUTE", s"proposal=$proposalId", currentBlock())
        result
      case Some(_) => Left("Quorum not reached")
      case None => Left("Proposal not found")
    }
  }

  // Expression evaluation with context binding
  private def evaluateExpression(expr: String, context: Map[String, Long]): Either[String, Long] = {
    parseExpression(expr).map(ast => evalAST(ast, context)) match {
      case Some(v) => Right(v)
      case None => Left("Evaluation failed")
    }
  }

  private def evalAST(expr: Expr, ctx: Map[String, Long]): Long = expr match {
    case Literal(v) => v
    case VarRef(n) => ctx.getOrElse(n, 0L)
    case BinOp(op, l, r) =>
      val lv = evalAST(l, ctx)
      val rv = evalAST(r, ctx)
      op match {
        case "+" => lv + rv
        case "-" => lv - rv
        case "*" => lv * rv
        case "/" => if (rv != 0) lv / rv else 0L
        case "%" => if (rv != 0) lv % rv else 0L
        case "==" => if (lv == rv) 1L else 0L
        case "!=" => if (lv != rv) 1L else 0L
        case "<" => if (lv < rv) 1L else 0L
        case ">" => if (lv > rv) 1L else 0L
      }
    case FuncCall(name, args) =>
      val evaluated = args.map(evalAST(_, ctx))
      name match {
        case "min" => evaluated.min
        case "max" => evaluated.max
        case "abs" => Math.abs(evaluated.head)
        case "sqrt" => Math.sqrt(evaluated.head.toDouble).toLong
      }
  }

  // Audit query endpoint - uses structured field/value matching only
  def queryAudit(field: String, value: String, requester: String): Seq[String] = {
    auditLog.append(requester, "AUDIT_QUERY", s"field=$field", currentBlock())
    val compiledFilter = auditLog.compileFilter(field, value)
    auditLog.query(compiledFilter).map(_.toString)
  }

  private def buildContext(p: Proposal): Map[String, Long] = {
    stateVars.toMap ++ Map("amount" -> 0L, "target" -> 0L, "votes_for" -> p.votes.count(_._2), "votes_against" -> p.votes.count(!_._2))
  }

  private def hasQuorum(p: Proposal): Boolean = {
    val totalVotes = p.votes.size
    val forVotes = p.votes.count(_._2)
    totalVotes > 0 && (forVotes * 100 / totalVotes) >= stateVars("quorum")
  }

  private def currentBlock(): Long = Instant.now.toEpochMilli / 12000

  // Parse simple expression language
  private def parseExpression(input: String): Option[Expr] = {
    Try {
      val tokens = tokenize(input)
      parseExpr(tokens, 0)._1
    }.toOption
  }

  private def tokenize(input: String): Array[String] = {
    input.split("""(?<=[+\-*/%()=!<>,])|(?=[+\-*/%()=!<>,])""")
      .map(_.trim).filter(_.nonEmpty)
  }

  private def parseExpr(tokens: Array[String], pos: Int): (Expr, Int) = {
    if (pos >= tokens.length) (Literal(0L), pos)
    else {
      val token = tokens(pos)
      if (token.forall(_.isDigit)) (Literal(token.toLong), pos + 1)
      else if (token.forall(c => c.isLetter || c == '_')) {
        if (pos + 1 < tokens.length && tokens(pos + 1) == "(") {
          // Function call
          val args = mutable.ListBuffer[Expr]()
          var p = pos + 2
          while (p < tokens.length && tokens(p) != ")") {
            if (tokens(p) == ",") p += 1
            else {
              val (arg, np) = parseExpr(tokens, p)
              args += arg
              p = np
            }
          }
          (FuncCall(token, args.toList), p + 1)
        } else (VarRef(token), pos + 1)
      }
      else (Literal(0L), pos + 1)
    }
  }
}
